export function questions(theme) {
  return theme.words.map((w, i) => ({
    id: `${theme.id}-${i}`,
    arabic: w[0],
    answer: w[2],
    options: Array.from({length: 4}, (_, n) => theme.words[(i + n) % theme.words.length][2]).sort((a, b) => a.localeCompare(b, 'id')),
    explanation: `${w[0]} (${w[1]}) berarti “${w[2]}”.`
  }));
}
